# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">ATMOSFERİN KATMANLARI VE TEMEL ÖZELLİKLERİ</text>\n  <rect x="25" y="42" width="320" height="202" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <rect x="40" y="52" width="290" height="28" rx="5" fill="#1e3a8a"/>\n  <text x="185" y="70" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">5. EKZOSFER (En dış katman, yapay uydular)</text>\n  <rect x="40" y="86" width="290" height="28" rx="5" fill="#1d4ed8"/>\n  <text x="185" y="104" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">4. TERMOSFER (İyonosfer: Radyo dalgaları, Kutup ışıkları)</text>\n  <rect x="40" y="120" width="290" height="28" rx="5" fill="#2563eb"/>\n  <text x="185" y="138" text-anchor="middle" font-size="11" font-weight="bold" fill="#ffffff">3. MEZOSFER (Gök taşlarının / meteorların parçalanması)</text>\n  <rect x="40" y="154" width="290" height="32" rx="5" fill="#60a5fa"/>\n  <text x="185" y="174" text-anchor="middle" font-size="11" font-weight="bold" fill="#0f172a">2. STRATOSFER (Ozonosfer: UV ışınlarını tutar, yatay hava)</text>\n  <rect x="40" y="192" width="290" height="42" rx="5" fill="#bae6fd" stroke="#0284c7" stroke-width="1.5"/>\n  <text x="185" y="210" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#0369a1">1. TROPOSFER (Gazların %75\'i, su buharının tamamı)</text>\n  <text x="185" y="226" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#0c4a6e">İklim ve hava olaylarının yaşandığı katman (8-16 km)</text>\n  <rect x="360" y="42" width="315" height="202" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="517" y="65" text-anchor="middle" font-size="13" font-weight="bold" fill="#166534">ATMOSFERİN BİLEŞİMİ VE ÖNEMİ</text>\n  <text x="378" y="92" font-size="11.5" font-weight="bold" fill="#14532d">• Sabit Gazlar: %78 Azot (N₂), %21 Oksijen (O₂)</text>\n  <text x="378" y="114" font-size="11.5" font-weight="bold" fill="#14532d">• %1 Asal Gazlar ve Değişken Gazlar (Su buharı, CO₂)</text>\n  <text x="378" y="142" font-size="11" fill="#334155">✓ Troposferde yerden yükseldikçe sıcaklık her</text>\n  <text x="388" y="158" font-size="11" font-weight="bold" fill="#15803d">200 metrede 1 °C (1000 m\'de 5 °C) azalır.</text>\n  <text x="378" y="182" font-size="11" fill="#334155">✓ Dünya\'nın aşırı ısınmasını ve soğumasını önler.</text>\n  <text x="378" y="204" font-size="11" fill="#334155">✓ Güneş ışınlarını dağıtarak gölge yerleri aydınlatır.</text>\n  <text x="378" y="226" font-size="11" fill="#334155">✓ Canlı yaşamı ve su döngüsü için vazgeçilmezdir.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HAVA DURUMU (METEOROLOJİ) İLE İKLİM (KLİMATOLOJİ) FARKLARI</text>\n  <rect x="25" y="45" width="315" height="195" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#854d0e">HAVA DURUMU (KISA SÜRELİ - DAR ALAN)</text>\n  <text x="42" y="96" font-size="11.5" font-weight="bold" fill="#713f12">• Süre: Saatlik, günlük veya haftalık (kısa süreli)</text>\n  <text x="42" y="120" font-size="11.5" font-weight="bold" fill="#713f12">• Alan: Dar bir alanda etkili ve hızla değişkendir</text>\n  <text x="42" y="144" font-size="11.5" font-weight="bold" fill="#713f12">• Bilim Dalı: Meteoroloji (Uzman: Meteorolog)</text>\n  <text x="42" y="168" font-size="11.5" font-weight="bold" fill="#713f12">• İfade Biçimi: Tahminîdir (Güneşli, sağanak yağışlı,</text>\n  <text x="52" y="186" font-size="11" fill="#334155">sisli, kar yağışlı, parçalı bulutlu, fırtınalı)</text>\n  <text x="42" y="214" font-size="10.5" fill="#854d0e">Örnek: &quot;Yarın Ankara\'da öğleden sonra kar bekleniyor.&quot;</text>\n  <rect x="360" y="45" width="315" height="195" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="517" y="68" text-anchor="middle" font-size="13" font-weight="bold" fill="#6b21a8">İKLİM (UZUN SÜRELİ - GENİŞ ALAN)</text>\n  <text x="377" y="96" font-size="11.5" font-weight="bold" fill="#581c87">• Süre: En az 30-35 yıllık uzun gözlem ortalaması</text>\n  <text x="377" y="120" font-size="11.5" font-weight="bold" fill="#581c87">• Alan: Geniş bölgelerde etkili ve durağandır</text>\n  <text x="377" y="144" font-size="11.5" font-weight="bold" fill="#581c87">• Bilim Dalı: Klimatoloji (Uzman: Klimatolog)</text>\n  <text x="377" y="168" font-size="11.5" font-weight="bold" fill="#581c87">• İfade Biçimi: Genel karakteri yansıtır (Kurak, ılıman,</text>\n  <text x="387" y="186" font-size="11" fill="#334155">her mevsim yağışlı, yazları sıcak ve kurak)</text>\n  <text x="377" y="214" font-size="10.5" fill="#6b21a8">Örnek: &quot;Akdeniz kıyılarında yazlar sıcak ve kurak geçer.&quot;</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#0f172a">HAVA OLAYLARININ GÜNLÜK HAYATA VE EKONOMİYE ETKİLERİ</text>\n  <rect x="25" y="45" width="205" height="195" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="127" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">ULAŞIM VE TRAFİK</text>\n  <text x="38" y="96" font-size="11" fill="#334155">• Yoğun sis ve fırtınada</text>\n  <text x="45" y="113" font-size="10.5" fill="#475569">hava ve deniz seferlerinin</text>\n  <text x="45" y="128" font-size="10.5" fill="#475569">iptal edilmesi</text>\n  <text x="38" y="155" font-size="11" fill="#334155">• Kar yağışı ve buzlanmada</text>\n  <text x="45" y="172" font-size="10.5" fill="#475569">kara yollarında kış lastiği</text>\n  <text x="45" y="187" font-size="10.5" fill="#475569">ve tuzlama tedbirleri</text>\n  <rect x="247" y="45" width="205" height="195" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="350" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">TARIM VE EKONOMİ</text>\n  <text x="260" y="96" font-size="11" fill="#334155">• İlkbahar geç donları ve</text>\n  <text x="267" y="113" font-size="10.5" fill="#475569">dolu yağışına karşı meyve</text>\n  <text x="267" y="128" font-size="10.5" fill="#475569">bahçelerinin korunması</text>\n  <text x="260" y="155" font-size="11" fill="#334155">• Ekim, gübreleme, ilaçlama,</text>\n  <text x="267" y="172" font-size="10.5" fill="#475569">sulama ve hasat zamanının</text>\n  <text x="267" y="187" font-size="10.5" fill="#475569">tahminlere göre planlanması</text>\n  <rect x="470" y="45" width="205" height="195" rx="10" fill="#fef2f2" stroke="#dc2626" stroke-width="2"/>\n  <text x="572" y="68" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#991b1b">ERKEN UYARI SİSTEMİ (MGM)</text>\n  <text x="483" y="96" font-size="11" font-weight="bold" fill="#15803d">• Yeşil Kod: Tehlike yok</text>\n  <text x="483" y="122" font-size="11" font-weight="bold" fill="#ca8a04">• Sarı Kod: Potansiyel tehlike</text>\n  <text x="483" y="148" font-size="11" font-weight="bold" fill="#ea580c">• Turuncu Kod: Tehlikeli durum</text>\n  <text x="483" y="174" font-size="11" font-weight="bold" fill="#dc2626">• Kırmızı Kod: Çok tehlikeli /</text>\n  <text x="493" y="191" font-size="10.5" fill="#991b1b">ekstrem meteorolojik olay</text>\n  <text x="572" y="220" text-anchor="middle" font-size="10.5" font-weight="bold" fill="#7f1d1d">Afet riskini azaltır, can korur.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
